/** Read-only research aggregation. All scores are inputs, NOT generated by this engine. */
export const DIMENSIONS = ["macro", "fundamental", "valuation", "technical", "sentiment", "catalyst", "risk"] as const;
export type Dimension = (typeof DIMENSIONS)[number];
export const WEIGHTS: Readonly<Record<Dimension, number>> = Object.freeze({
  macro: 5, fundamental: 20, valuation: 20, technical: 15,
  sentiment: 10, catalyst: 15, risk: 15,
});
export type ResearchSignal = {
  dimension: Dimension;
  score: number; // 0..100; for risk only, HIGHER means MORE downside risk
  source: string;
  rationale: string;
};
export type ResearchInput = {
  symbol: string;
  assetClass: "equity" | "crypto";
  signals: ResearchSignal[];
};
export type ResearchBreakdown = ResearchSignal & { weightPct: number; contribution: number };
export type ResearchReport = {
  symbol: string;
  assetClass: ResearchInput["assetClass"];
  status: "complete" | "insufficient-data";
  compositeScore: number | null;
  coveragePct: number;
  breakdown: ResearchBreakdown[];
  missingDimensions: Dimension[];
  warnings: string[];
  simulation: true;
  executionEnabled: false;
};
const round = (n: number) => Math.round(n * 100) / 100;
/** Aggregates supplied signals without fetching prices, calling an LLM, or placing orders. */
export function evaluateResearch(input: ResearchInput): ResearchReport {
  const symbol = input.symbol.toUpperCase();
  if (!/^[A-Z0-9][A-Z0-9.-]{0,14}$/.test(symbol)) throw new Error("Invalid symbol");
  if (!Array.isArray(input.signals)) throw new Error("Signals must be an array");
  const seen = new Set<Dimension>();
  const breakdown: ResearchBreakdown[] = [];
  for (const signal of input.signals) {
    if (!DIMENSIONS.includes(signal.dimension)) throw new Error("Unknown research dimension");
    if (seen.has(signal.dimension)) throw new Error(`Duplicate dimension: ${signal.dimension}`);
    if (!Number.isFinite(signal.score) || signal.score < 0 || signal.score > 100) {
      throw new Error(`Invalid score: ${signal.dimension}`);
    }
    if (!signal.source.trim() || !signal.rationale.trim()) throw new Error("Signal provenance and rationale are required");
    seen.add(signal.dimension);
    const adjusted = signal.dimension === "risk" ? 100 - signal.score : signal.score;
    breakdown.push({ ...signal, weightPct: WEIGHTS[signal.dimension], contribution: round(adjusted * WEIGHTS[signal.dimension] / 100) });
  }
  const missingDimensions = DIMENSIONS.filter(d => !seen.has(d));
  const complete = missingDimensions.length === 0;
  const coveragePct = DIMENSIONS.reduce((sum, d) => sum + (seen.has(d) ? WEIGHTS[d] : 0), 0);
  const warnings: string[] = ["Synthetic research inputs. No live prices, AI calls, or investment recommendations."];
  if (!complete) warnings.push("Composite withheld because one or more dimensions are missing.");
  if ((input.signals.find(s => s.dimension === "risk")?.score ?? 0) >= 75) {
    warnings.push("Illustrative high-risk gate triggered; additional review would be required.");
  }
  return {
    symbol, assetClass: input.assetClass,
    status: complete ? "complete" : "insufficient-data",
    compositeScore: complete ? round(breakdown.reduce((sum, row) => sum + row.contribution, 0)) : null,
    coveragePct, breakdown, missingDimensions, warnings,
    simulation: true, executionEnabled: false,
  };
}
